# Generated by scripts/homebrew-formulas.py in tinhthanh/shipyard for v0.3.31-fork.12.
class Vetgo < Formula
  desc "Run coding agents on your own boxes: the berth CLI and laptop agent"
  homepage "https://github.com/tinhthanh/shipyard"
  version "0.3.31-fork.12"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.12/berth-darwin-arm64.tar.gz"
      sha256 "bfe705f4747df73b7f47c6ba6c4543a8a8fa65c0392dca29bf7e2f53c05215e4"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.12/berth-darwin-amd64.tar.gz"
      sha256 "999cc9bdd2186eed031bb3620454967978be3bb5a88b76078a3b41bfd85c0593"
    end

    # The berthd builds `berth upgrade` puts on Mac boxes; the Linux ones
    # come in berth's own archive.
    resource "berthd-darwin-arm64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.12/berthd-darwin-arm64.tar.gz"
      sha256 "53ddb2ce3bd9d4f443d7fc74081e4f40045bec7fd270395101c03233d5270e39"
    end
    resource "berthd-darwin-amd64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.12/berthd-darwin-amd64.tar.gz"
      sha256 "30d8ed6debc11d235aadf6feea49ecc7daa0c7fc3c2d7d327048c5299d57b58e"
    end
  end
  on_linux do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.12/berth-linux-arm64.tar.gz"
      sha256 "cfc838152454b3af48c330a09bdd0852da08860d1ad45e26867faf11e5d98458"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.12/berth-linux-amd64.tar.gz"
      sha256 "5ef1f50dcb2cfc1706b3d3fb029ca1b91694187e361287d66035fc23943020bc"
    end
  end

  def install
    # berth looks beside its own file (through the link in bin) for the
    # berthd and tmux builds it uploads to boxes.
    libexec.install Dir["*"]
    if OS.mac?
      %w[arm64 amd64].each do |arch|
        resource("berthd-darwin-#{arch}").stage { libexec.install "berthd" => "berthd-darwin-#{arch}" }
      end
    end
    bin.install_symlink libexec/"berth"
  end

  def caveats
    <<~EOS
      Start the laptop agent, and have it start when you log in:
        berth agent install
      Add a box: berth add ssh USER@HOST (see berth help).
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/berth version")
  end
end
